class MinStack {
    private final Deque<Integer> stack = new ArrayDeque<>();
    private final Deque<Integer> mins = new ArrayDeque<>();

    void push(int x) {
        stack.push(x);
        mins.push(mins.isEmpty() ? x : Math.min(x, mins.peek()));
    }

    void pop() {
        stack.pop();
        mins.pop();
    }

    int top() {
        return stack.peek();
    }

    int getMin() {
        return mins.peek();
    }
}

