int evalRPN(String[] tokens) {
    Deque<Integer> stack = new ArrayDeque<>();
    for (int i = 0; i < tokens.length; i++) {
        String t = tokens[i];
        if (t.equals("+") || t.equals("-") || t.equals("*") || t.equals("/")) {
            int b = stack.pop(), a = stack.pop();
            int r = switch (t) {
                case "+" -> a + b;
                case "-" -> a - b;
                case "*" -> a * b;
                default -> a / b;
            };
            stack.push(r);
        } else {
            stack.push(Integer.parseInt(t));
        }
    }
    return stack.pop();
}

