            b, a = stack.pop(), stack.pop()
            if t == "+": r = a + b
            elif t == "-": r = a - b
            elif t == "*": r = a * b
            else: r = int(a / b)  # truncate toward zero
            stack.append(r)
        else:
            stack.append(int(t))
    return stack.pop()

